-- Ulduar, Archivum: the Archivum Console story, Brann Bronzebeard, Prospector Doren and Loren, Archmage Rhydian and
-- High Explorer Dellorah, from TrinityCore 3.3.5: their SmartAI, texts, waypoint paths and the spawns the world lacked
-- (Brann, the Archivum System, Prospector Doren in the 10-player raid and Prospector Loren in the 25-player raid).
-- TrinityCore's difficulty flags 0x2 (10 player) and 0x4 (25 player) are 0x8 and 0x10 here. The console's
-- "make inert" and "make active" actions are the not-selectable object flag here.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (33235, 33696, 33701, 33761, 33861, 33862, 33877, 33956, 33957);
UPDATE `gameobject_template` SET `AIName` = 'SmartGameObjectAI' WHERE `entry` = 194555;
DELETE FROM `smart_scripts` WHERE (`source_type` = 0 AND `entryorguid` IN (33235, 33696, 33701, 33761, 33861, 33862, 33877, 33956, 33957)) OR (`source_type` = 1 AND `entryorguid` = 194555) OR (`source_type` = 9 AND `entryorguid` IN (3323500, 3369600, 3370100, 3395700, 19455500, 19455501, 19455502, 19455503, 19455504, 19455505));
DELETE FROM `creature_text` WHERE `entry` IN (33235, 33626, 33686, 33696, 33701, 33874);
DELETE FROM `waypoints` WHERE `entry` IN (265881, 269569, 271649);
DELETE FROM `creature` WHERE `guid` IN (8431000, 8431001, 8431002, 8431003);
